      "keystrokes": "cat > main.cpp << 'EOF'\n#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Node {\n    long long cnt;\n    string pref; // first up to 3 chars\n    string suff; // last up to 3 chars\n    long long len;\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int t;\n    if(!(cin >> t)) return 0;\n    while(t--) {\n        int n; cin >> n;\n        unordered_map<string, Node> mp;\n        string lastVar;\n        for(int i = 0; i < n; ++i) {\n            string lhs, op;\n            cin >> lhs; cin >> op;\n            if(op == \":=\") {\n                string s; cin >> s;\n                long long len = (long long)s.size();\n                long long cnt = 0;\n                for(size_t p = 0; p + 3 < s.size(); ++p) {\n                    if(s.substr(p, 4) == \"haha\") cnt++;\n                }\n                Node nd;\n                nd.cnt = cnt;\n                nd.len = len;\n                nd.pref = s.substr(0, (size_t)min<long long>(3, len));\n                nd.suff = s.substr(len - min<long long>(3, len));\n                mp[lhs] = nd;\n                lastVar = lhs;\n            } else if(op == \"=\") {\n                string a, plus, b; cin >> a; cin >> plus; cin >> b; // a + b\n                Node A = mp[a];\n                Node B = mp[b];\n                Node X;\n                long long cross = 0;\n                for(int k = 1; k <= 3; ++k) {\n                    if(A.len >= k && B.len >= 4 - k) {\n                        string left = A.suff.substr(A.suff.size() - k);\n                        string right = B.pref.substr(0, 4 - k);\n                        if(left + right == \"haha\") cross++;\n                    }\n                }\n                X.cnt = A.cnt + B.cnt + cross;\n                X.len = A.len + B.len;\n                if(X.len > (long long)1e18) X.len = (long long)1e18; // cap to avoid overflow\n                string combinedPref = A.pref + B.pref;\n                if(combinedPref.size() > 3) combinedPref.resize(3);\n                X.pref = combinedPref;\n                string combinedSuff = A.suff + B.suff;\n                if(combinedSuff.size() > 3) X.suff = combinedSuff.substr(combinedSuff.size() - 3);\n                else X.suff = combinedSuff;\n                mp[lhs] = X;\n                lastVar = lhs;\n            }\n        }\n        cout << mp[lastVar].cnt << \"\\n\";\n    }\n    return 0;\n}\nEOF\n\ng++ -std=c++17 -O2 -pipe -o main main.cpp\n\n./main << 'EOF'\n4\n6\na := h\nb := aha\nc = a + b\nc = c + c\ne = c + c\nd = a + c\n15\nx := haha\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\nx = x + x\n1\nhaha := hah\n5\nhaahh := aaaha\nahhhh = haahh + haahh\nhaahh = haahh + haahh\nahhhh = ahhhh + haahh\nahhaa = haahh + ahhhh\nEOF\n"
